// This package has no completion node: closing the loop is the CMMS's
// act, and at the OT boundary it arrives as a message. The SDK builds the
// event, on the same correlation_id, pointing back at the intent.
const intent = msg.payload;
msg.payload = new iaes.MaintenanceCompletion({
    asset_id: intent.asset.asset_id,
    asset_name: intent.asset.asset_name,
    plant: intent.asset.plant,
    area: intent.asset.area,
    source: "acme.cmms",
    work_order_id: "WO-2026-0912",
    status: "completed",
    correlation_id: intent.correlation_id,
    source_event_id: intent.event_id,
}).toJSON();
return msg;

// An event type IAES does not publish, in a namespace the producer
// controls. There is no node for it and there does not need to be: the
// envelope is what interoperates. Written by hand, no content_hash, and
// iaes-validate must accept it -- the catalog is open.
const previous = msg.payload;
msg.payload = {
    spec_version: previous.spec_version,
    event_type: "acme.press_stroke",
    event_id: crypto.randomUUID(),
    correlation_id: previous.correlation_id,
    timestamp: new Date().toISOString(),
    source: "acme.press_line",
    asset: { asset_id: previous.asset.asset_id },
    data: { strokes: 412, tonnage_peak: 88.4 },
};
return msg;
